const res = $context.getHttpResponse("documentoResponse");
let status = 0;
try {
  status = Number(typeof res?.status === "function" ? res.status() : res?.status) || 0;
} catch (e) {
  status = 0;
}
let data = {};
try {
  data = typeof res?.json === "function" ? await res.json() : (res?.json ?? res?.data ?? {});
} catch (e) {
  data = {};
}
if (typeof data === "string") {
  try { data = JSON.parse(data); } catch (e) { data = {}; }
}
if (!data || typeof data !== "object") data = {};
const ok = status >= 200 && status < 300;
const mensaje = String(data.message ?? data.error?.message ?? data.detail ?? "");
const codigo = String(data.code ?? data.errorCode ?? data.error?.code ?? (typeof data.error === "string" ? data.error : ""));
$utils.logger.log("documentoResponse", JSON.stringify({ status, codigo }));
const documento = data.document ?? data.data?.document ?? {};
let salida = "error";
if (ok && typeof documento.downloadUrl === "string" && documento.downloadUrl) {
  salida = "documento";
  // El PDF lo envía el siguiente paso; el enlace no se devuelve al agente.
  $context.set("downloadUrl", documento.downloadUrl);
} else if (status === 401) {
  salida = "rechazado";
  $output.set("rechazado", { ok: false, reason: "sesion_expirada", code: codigo || "UNAUTHORIZED", message: mensaje || "La sesión expiró." });
} else if (status >= 400 && status < 500) {
  salida = "rechazado";
  $output.set("rechazado", { ok: false, reason: "no_elegible", code: codigo || "HTTP_" + status, message: mensaje });
} else {
  $output.set("error", { ok: false, code: codigo || "HTTP_" + status, message: mensaje || "No se pudo generar el documento." });
}
$context.set("salida", salida);

$output.set("error", {
  ok: false,
  code: "TECNICO",
  message: "No fue posible comunicarse con el servicio de Crediviva.",
});

function inp(k, d) {
  try {
    const v = $input.get(k);
    return v === undefined || v === null || v === "" ? d : v;
  } catch (e) {
    return d;
  }
}
async function secreto(nombre) {
  try {
    return String((await $secret.get(nombre)) || "");
  } catch (e) {
    return "";
  }
}
let fallo = "";
const ambiente = String(inp("ambiente", "")).trim().toLowerCase();
if (ambiente !== "staging" && ambiente !== "production") {
  fallo = "El ambiente debe ser staging o production (recibido: " + ambiente + ").";
}
let baseUrl = "";
let apiKey = "";
if (!fallo) {
  const sufijo = ambiente.toUpperCase();
  baseUrl = (await secreto("CREDIVIVA_BASE_URL_" + sufijo)).replace(/\/+$/, "");
  apiKey = (await secreto("CREDIVIVA_API_KEY_" + sufijo));
  if (!/^https:\/\//.test(baseUrl)) fallo = "Falta el secreto CREDIVIVA_BASE_URL_" + sufijo + ".";
  else if (apiKey.length < 8) fallo = "Falta el secreto CREDIVIVA_API_KEY_" + sufijo + ".";
}
$context.set("apiKey", apiKey);
const sessionToken = String(inp("sessionToken", "")).trim();
if (!fallo && sessionToken.length < 8) fallo = "Falta el token de sesión.";
const tratamientos = ["SEÑORES", "SEÑORA", "SEÑOR"];
const addressedTo = String(inp("addressedTo", "")).trim().toUpperCase().replace("SENORES", "SEÑORES").replace("SENORA", "SEÑORA").replace("SENOR", "SEÑOR");
const recipientName = String(inp("recipientName", "")).trim().slice(0, 120);
if (!fallo && !tratamientos.includes(addressedTo)) fallo = "Tratamiento inválido: use SEÑORES, SEÑORA o SEÑOR.";
if (!fallo && recipientName.length < 2) fallo = "Falta el nombre del destinatario.";
const query = "?addressedTo=" + encodeURIComponent(addressedTo) + "&recipientName=" + encodeURIComponent(recipientName);
$context.set("sessionToken", sessionToken);
$context.set("url", baseUrl + "/v1/whatsapp-customer-api/document-service/cancellation-letter" + query);
if (fallo) {
  $output.set("error", { ok: false, code: "CONFIGURACION", message: fallo });
}
$context.set("prepOk", fallo ? "no" : "si");
